import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"技能触发器","description":"","frontmatter":{},"headers":[],"relativePath":"modules/mobs/triggers.md","filePath":"modules/mobs/triggers.md","lastUpdated":0}`),a={name:`modules/mobs/triggers.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="技能触发器" tabindex="-1">技能触发器 <a class="header-anchor" href="#技能触发器" aria-label="Permalink to “技能触发器”">​</a></h1><p>生物定义 <code>actions</code> 能绑定的全部触发器, 以及每条动作能用到的上下文变量如下</p><p>生物定义里的 <code>actions</code> 节点把触发器和 CoreLib 动作管道绑在一起. 动作由 <strong>EmakiCoreLib</strong> 的动作管道执行 (CoreLib 是硬依赖), <strong>不需要</strong>安装 EmakiSkills. 旧键 <code>skills</code> 仍会作为兼容回退被读取, 读取时会提示 WARN, 建议尽快迁移过来</p><h2 id="触发器列表" tabindex="-1">触发器列表 <a class="header-anchor" href="#触发器列表" aria-label="Permalink to “触发器列表”">​</a></h2><table tabindex="0"><thead><tr><th>触发器</th><th>触发时机</th><th>上下文对象</th></tr></thead><tbody><tr><td><code>on_spawn</code></td><td>生物刷出时 (在 <code>MobFactory</code> 里, Boss 血条与模型挂载之后立刻执行)</td><td>—</td></tr><tr><td><code>on_death</code></td><td>生物死亡时</td><td><code>killer</code> (击杀者, 只在有存活的击杀者时才提供)</td></tr><tr><td><code>on_target</code></td><td>生物锁定新目标时</td><td><code>target</code> (只在目标非空时提供)</td></tr><tr><td><code>on_damage_give</code></td><td>这只生物作为攻击者造成伤害时</td><td><code>target</code> (只在挨打的是生物实体时才提供)</td></tr><tr><td><code>on_damage_take</code></td><td>这只生物受到伤害时</td><td><code>attacker</code> (只在攻击它的是生物实体时才提供)</td></tr><tr><td><code>on_kill</code></td><td>这只生物击杀某个实体时</td><td><code>victim</code> (被击杀的实体)</td></tr><tr><td><code>on_shoot</code></td><td>这只生物射出弹射物时</td><td>—</td></tr><tr><td><code>on_explode</code></td><td>这只生物爆炸时 (比如苦力怕)</td><td>—</td></tr><tr><td><code>on_teleport</code></td><td>这只生物传送时</td><td>—</td></tr><tr><td><code>on_transform</code></td><td>这只生物变形时 (比如僵尸猪灵变身)</td><td>—</td></tr><tr><td><code>on_health_threshold_&lt;百分比&gt;</code></td><td>生物血量第一次降到这个百分比或者更低时</td><td>—</td></tr></tbody></table><p>&quot;上下文对象&quot;这一列的对象由 EmakiMobs 通过 CoreLib 的动作上下文键传进去; 没提供时, 对应的源段 (比如 <code>killer</code>) 会返回空结果, 那条动作行就不会被执行. <strong>这里没有伤害量对象</strong> (<code>on_damage_give</code> / <code>on_damage_take</code> 都不提供 <code>damage</code>), 需要伤害数值的话请改用 CoreLib 的其他手段</p><h3 id="血量阈值触发器" tabindex="-1">血量阈值触发器 <a class="header-anchor" href="#血量阈值触发器" aria-label="Permalink to “血量阈值触发器”">​</a></h3><p><code>on_health_threshold_&lt;百分比&gt;</code> 的百分比档位固定为五档, 只有以下五个键名会被触发:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>on_health_threshold_90</span></span>
<span class="line"><span>on_health_threshold_75</span></span>
<span class="line"><span>on_health_threshold_50</span></span>
<span class="line"><span>on_health_threshold_25</span></span>
<span class="line"><span>on_health_threshold_10</span></span></code></pre></div><p>写其他数字 (如 <code>on_health_threshold_80</code>) 不会报错, 但永远不触发</p><p>每个档位对同一只生物<strong>只会触发一次</strong>. 生物受到伤害时按 90 → 10 的顺序检查, 一次伤害跨过好几个档位时, 被跨过的档位会在同一次伤害里依次触发. 阈值按 <code>当前生命值 / 最大生命值属性值</code> 算, 最大生命值属性缺失或者不是正数时就不做阈值检查</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>血量阈值是跟着伤害事件一起检测的, 所以 <code>on_damage_take</code> 和命中的阈值触发器会同时执行</p></div><h2 id="动作字符串格式" tabindex="-1">动作字符串格式 <a class="header-anchor" href="#动作字符串格式" aria-label="Permalink to “动作字符串格式”">​</a></h2><p>每个触发器对应一组 CoreLib 动作管道字符串, 格式为:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[选择器 |] 动作名 [参数=值 ...]</span></span></code></pre></div><h3 id="常用选择器" tabindex="-1">常用选择器 <a class="header-anchor" href="#常用选择器" aria-label="Permalink to “常用选择器”">​</a></h3><table tabindex="0"><thead><tr><th>选择器</th><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><code>self</code></td><td>CoreLib</td><td>触发这个事件的生物自己 (管道里的施法者)</td></tr><tr><td><code>target</code></td><td>EmakiMobs</td><td>当前事件的目标实体 (<code>on_target</code>, <code>on_damage_give</code>)</td></tr><tr><td><code>killer</code></td><td>EmakiMobs</td><td>击杀这只生物的实体 (<code>on_death</code>)</td></tr><tr><td><code>victim</code></td><td>EmakiMobs</td><td>被这只生物击杀的实体 (<code>on_kill</code>)</td></tr><tr><td><code>attacker</code></td><td>EmakiMobs</td><td>攻击这只生物的实体 (<code>on_damage_take</code>)</td></tr><tr><td><code>nearby radius=&lt;n&gt; include_players=true</code></td><td>CoreLib</td><td>半径范围内的实体.<strong>玩家默认会被排除</strong>: <code>include_players</code> 默认是 <code>false</code>, 只写 <code>type=player</code> 选不出任何目标, 必须显式加上 <code>include_players=true</code></td></tr></tbody></table><p>EmakiMobs 注册的四个选择器 (<code>target</code> / <code>killer</code> / <code>victim</code> / <code>attacker</code>) 都依赖上面列的上下文对象: 只有对应触发器的事件里真的有这个对象时, 才能解析出目标</p><h3 id="动作示例" tabindex="-1">动作示例 <a class="header-anchor" href="#动作示例" aria-label="Permalink to “动作示例”">​</a></h3><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_spawn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向附近 20 格内所有玩家发送消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=20 include_players=true | send_message text=&#39;&lt;red&gt;精英僵尸降临！&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 在自身位置播放粒子效果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=30 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_death</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向击杀者给予经验</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | give_exp amount=80&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向附近玩家广播消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=50 include_players=true | send_message text=&#39;&lt;green&gt;精英僵尸已被击败！&#39;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_give</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 对被攻击目标施加减速效果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target | give_potion_effect type=SLOWNESS level=1 duration=3s&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 受伤时在自身位置产生火焰粒子</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=10 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 锁定目标时播放音效</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | play_sound sound=minecraft:entity.skeleton.ambient volume=1.0 pitch=0.7&quot;</span></span></code></pre></div><h2 id="emakimobs-注册的源段与动作段" tabindex="-1">EmakiMobs 注册的源段与动作段 <a class="header-anchor" href="#emakimobs-注册的源段与动作段" aria-label="Permalink to “EmakiMobs 注册的源段与动作段”">​</a></h2><p>除了 CoreLib 自带的内容, EmakiMobs 还向动作系统注册了 8 个段 (启动日志里会输出注册数量和期望值 8): 4 个源段 <code>attacker</code> / <code>killer</code> / <code>victim</code> / <code>target</code>, 4 个动作段 <code>summon_mob</code> / <code>mob_play_animation</code> / <code>mob_stop_animation</code> / <code>mob_set_model</code>. 动作行编译失败时, 控制台会输出 <code>技能编译错误: mob=&lt;id&gt; trigger=&lt;触发器&gt; line=&lt;行号&gt; reason=&lt;原因&gt;</code>, 这一行被跳过, 同个触发器里的其他行继续执行</p><h3 id="summon-mob-—-召唤生物定义" tabindex="-1"><code>summon_mob</code> — 召唤生物定义 <a class="header-anchor" href="#summon-mob-—-召唤生物定义" aria-label="Permalink to “summon_mob — 召唤生物定义”">​</a></h3><p>在目标位置召唤一只 EmakiMobs 生物定义</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>mob_id</code></td><td>string</td><td>是</td><td>无</td><td>已加载的生物定义 id (区分大小写)</td><td>要召唤的生物定义; 缺失或者空白时按配置错误 (<code>INVALID_CONFIG</code>) 返回, 没注册的 id 也一样按配置错误返回</td></tr><tr><td><code>count</code></td><td>int</td><td>否</td><td><code>1</code></td><td><code>≥ 1</code> (小于 1 按 1 处理)</td><td>召唤的数量; 会在目标位置逐个生成</td></tr></tbody></table><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 在自身位置召唤两只火焰守卫</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | summon_mob mob_id=fire_guardian count=2&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_health_threshold_50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 半血时在击杀者位置召唤一只随从</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | summon_mob mob_id=boss_minion&quot;</span></span></code></pre></div><p>这条动作要求目标能解析出位置 (执行域是位置区域). 目标没有位置时返回 <code>skipped</code>; 全部召唤都失败时返回 <code>INTERNAL_ERROR</code></p><h3 id="模型动作段" tabindex="-1">模型动作段 <a class="header-anchor" href="#模型动作段" aria-label="Permalink to “模型动作段”">​</a></h3><p><code>mob_play_animation</code>, <code>mob_stop_animation</code>, <code>mob_set_model</code> 的参数与行为见<a href="./models.html">实体模型与动画</a>的&quot;动作段&quot;一节</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>动作字符串的完整语法和所有可用动作都由 <strong>EmakiCoreLib</strong> 提供. 各动作及其参数的格式请参阅 CoreLib 文档</p></div>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};